package br.com.axecloud.app.feature.store
data class StoreProduct(val id:String,val name:String,val description:String,val price:Double,val stock:Int,val minimum:Int,val category:String,val image:String)
data class StoreOrder(val id:String,val childName:String,val type:String,val payment:String,val summary:String,val total:Double,val createdAt:String)
data class ProductForm(val name:String="",val description:String="",val price:String="",val stock:String="",val minimum:String="",val category:String="Velas",val image:String=""){companion object{fun from(p:StoreProduct)=ProductForm(p.name,p.description,p.price.toString(),p.stock.toString(),p.minimum.toString(),p.category,p.image)}}
data class StoreUiState(val loading:Boolean=true,val saving:Boolean=false,val products:List<StoreProduct> = emptyList(),val orders:List<StoreOrder> = emptyList(),val cart:Map<String,Int> = emptyMap(),val isFilho:Boolean=false,val query:String="",val category:String="Todos",val editor:StoreProduct?=null,val editorOpen:Boolean=false,val cartOpen:Boolean=false,val actionId:String?=null,val error:String?=null,val message:String?=null){val visible get()=products.filter{(category=="Todos"||it.category==category)&&(query.isBlank()||(it.name+it.description).contains(query,true))};val categories get()=listOf("Todos")+products.map{it.category}.distinct();val cartCount get()=cart.values.sum();val cartTotal get()=cart.entries.sumOf{(id,q)->(products.find{it.id==id}?.price?:0.0)*q}}
